13	export interface SubState {
14	  selectedPanel: string;
15	  addons: Record<string, never>;
16	}
17	
18	export interface SubAPI {
19	  /**
20	   * Returns a collection of elements of a specific type.
21	   *
22	   * @template T - The type of the elements in the collection.
23	   * @param {Addon_Types | Addon_TypesEnum.experimental_PAGE} type - The type of the elements to
24	   *   retrieve.
25	   * @returns {Addon_Collection<T>} - A collection of elements of the specified type.
26	   * @protected This is used internally in storybook's manager.
27	   */
28	  getElements: <
29	    T extends
30	      | Addon_Types
31	      | Addon_TypesEnum.experimental_PAGE
32	      | Addon_TypesEnum.experimental_TEST_PROVIDER,
33	  >(
34	    type: T
35	  ) => Addon_Collection<Addon_TypesMapping[T]>;
36	  /**
37	   * Returns the id of the currently selected panel.
38	   *
39	   * @returns {string} - The ID of the currently selected panel.
40	   */
41	  getSelectedPanel: () => string;
42	  /**
43	   * Sets the currently selected panel via it's ID.
44	   *
45	   * @param {string} panelName - The ID of the panel to select.
46	   * @returns {void}
47	   */
48	  setSelectedPanel: (panelName: string) => void;
49	  /**
50	   * Sets the state of an addon with the given ID.
51	   *
52	   * @deprecated This API might get dropped, if you are using this, please file an issue.
53	   * @template S - The type of the addon state.
54	   * @param {string} addonId - The ID of the addon to set the state for.
55	   * @param {S | API_StateMerger<S>} newStateOrMerger - The new state to set, or a function which
56	   *   receives the current state and returns the new state.
57	   * @param {Options} [options] - Optional options for the state update.
58	   * @returns {Promise<S>} - A promise that resolves with the new state after it has been set.
59	   */
60	  setAddonState<S>(
61	    addonId: string,
62	    newStateOrMerger: S | API_StateMerger<S>,
63	    options?: Options
64	  ): Promise<S>;
65	  /**
66	   * Returns the state of an addon with the given ID.
67	   *
68	   * @deprecated This API might get dropped, if you are using this, please file an issue.
69	   * @template S - The type of the addon state.
70	   * @param {string} addonId - The ID of the addon to get the state for.
71	   * @returns {S} - The state of the addon with the given ID.
72	   */
73	  getAddonState<S>(addonId: string): S;
74	}
75	
76	export function ensurePanel(
77	  panels: Addon_Collection<Addon_BaseType>,
78	  selectedPanel?: string,
79	  currentPanel?: string
80	) {
81	  const keys = Object.keys(panels);
82	
83	  if (keys.indexOf(selectedPanel!) >= 0) {
84	    return selectedPanel;
85	  }
86	
87	  if (keys.length) {
88	    return keys[0];
89	  }
90	  return currentPanel;
91	}
92	
93	export const init: ModuleFn<SubAPI, SubState> = ({ provider, store, fullAPI }): any => {
94	  const api: SubAPI = {
95	    getElements: (type) => provider.getElements(type),
96	    getSelectedPanel: (): any => {
97	      const { selectedPanel } = store.getState();
98	      return ensurePanel(api.getElements(Addon_TypesEnum.PANEL), selectedPanel, selectedPanel);
99	    },
100	    setSelectedPanel: (panelName) => {
101	      store.setState({ selectedPanel: panelName }, { persistence: 'session' });
102	    },
103	    setAddonState<S>(
104	      addonId: string,
105	      newStateOrMerger: S | API_StateMerger<S>,
106	      options?: Options
107	    ): Promise<S> {
108	      const merger = (
109	        typeof newStateOrMerger === 'function' ? newStateOrMerger : () => newStateOrMerger
110	      ) as API_StateMerger<S>;
111	      return store
112	        .setState(
113	          (s) => ({ ...s, addons: { ...s.addons, [addonId]: merger(s.addons[addonId]) } }),
114	          options
115	        )
116	        .then(() => api.getAddonState(addonId));
117	    },
118	    getAddonState: (addonId) => {
119	      return store.getState().addons[addonId] || globalThis?.STORYBOOK_ADDON_STATE[addonId];
120	    },
121	  };
122	
123	  return {
124	    api,
125	    state: {
126	      selectedPanel: ensurePanel(
127	        api.getElements(Addon_TypesEnum.PANEL),
128	        store.getState().selectedPanel
129	      ),
130	      addons: {},
131	    },
132	  };
133	};
